targets.expr:
100 * (
  ( sum by (request_path) (
    rate(istio_requests_total{
      reporter="destination",
      destination_app="$configuration",
      request_path!~"probe|metadata|blocked|other|/metrics|/|/events|.*/readyz|.*/livez|.*/healthz|.*/openapi.*|.*/docs|.*/clear_cache.*|/wait-for-drain",
      response_code=~"2..", grpc_response_status=~"0|"
    }[$__rate_interval])
  ) )
  or ( sum by (request_path) (
    rate(istio_requests_total{
      reporter="destination",
      destination_app="$configuration",
      request_path!~"probe|metadata|blocked|other|/metrics|/|/events|.*/readyz|.*/livez|.*/healthz|.*/openapi.*|.*/docs|.*/clear_cache.*|/wait-for-drain"
    }[$__rate_interval])
  ) ) * 0
) / (
  sum by (request_path) (
    rate(istio_requests_total{
      reporter="destination",
      destination_app="$configuration",
      request_path!~"probe|metadata|blocked|other|/metrics|/|/events|.*/readyz|.*/livez|.*/healthz|.*/openapi.*|.*/docs|.*/clear_cache.*|/wait-for-drain"
    }[$__rate_interval])
  ) > 0
)

